import json,pathlib
root=pathlib.Path(__file__).resolve().parent
j=json.loads((root/'data/daily/2026-11-08.provisional.json').read_text())
players=j['players']; eligible=[p for p in players if p['minutes']>8]
top=sorted(eligible,key=lambda p:(-p['raw_qpix_shadow'],p['name']))[:10]
bottom=sorted(eligible,key=lambda p:(p['raw_qpix_shadow'],p['name']))[:10]
teams={'PHI':'Philadelphia 76ers','CHI':'Chicago Bulls','LAL':'Los Angeles Lakers','DET':'Detroit Pistons','UTA':'Utah Jazz','MIN':'Minnesota Timberwolves','BKN':'Brooklyn Nets','DAL':'Dallas Mavericks','BOS':'Boston Celtics','MIL':'Milwaukee Bucks','NOP':'New Orleans Pelicans','LAC':'Los Angeles Clippers','MIA':'Miami Heat','SAC':'Sacramento Kings'}
lines=['QCORE LABS QPIX™ NBA DAILY PERFORMANCE INDEX','Sunday, November 8, 2026 — PROVISIONAL SHADOW REPORT','7 FINAL GAMES | 161 PLAYERS EVALUATED','', 'NBA FINAL SCORES','']
for g in j['games']:
    lines.append(f"{teams[g['away_alias']]} {g['away_points']} – {teams[g['home_alias']]} {g['home_points']}")
lines+=['', 'COOPER FLAGG TAKES THE NIGHT — AND THE WHOLE GAME MATTERS','', 'Cooper Flagg headlines the November 8 QPIX provisional rankings with a 101.2 score after producing 25 points, five rebounds and 12 assists as Dallas beat Brooklyn 130–93. A complete playmaking performance, not simply the highest scoring total, put him on top.','', 'QPIX TOP 10 — RAW SCORE AND QPIX-R','']
for i,p in enumerate(top,1):
    lines.append(f"{i}. {p['name']} ({p['team']}) — QPIX {p['raw_qpix_shadow']:.1f} | QPIX-R {p['qpix_r_shadow']:.1f} | Q-OffR {p['qcore_q_offr']:.2f} | Q-DefR {p['qcore_q_defr']:.2f}")
lines+=['', 'THE PERFORMANCES BEHIND THE NUMBERS','', 'Flagg recorded 25 points, five rebounds and 12 assists in only 28 minutes. His estimated 159.01 Q-OffR shows the offensive value of combining scoring and facilitation; his 95.30 Q-DefR indicates a solid two-way profile within this game, subject to prototype validation.','', 'Kevin Huerter had 24 points, five rebounds, five assists, two steals and five blocks for Detroit. That is seven combined steals and blocks, with just one turnover. Even in a five-point Pistons loss, his all-around line delivered a 91.4 QPIX, second overall.','', 'Austin Reaves exploded for 43 points, five rebounds and four assists as the Lakers won in Detroit, 121–116. He committed only one turnover. His 82.3 RAW QPIX ranks third, and his 74.6 QPIX-R shows why the referee-normalized companion score should be read beside, not instead of, RAW.','', 'Mitchell Robinson provided the most striking defensive contrast of the night: 12 points, seven rebounds, four steals and a block in just 18 minutes for Boston. His provisional Q-DefR of 84.15 was exceptional, helping produce 81.3 QPIX despite a modest scoring total.','', 'Giannis Antetokounmpo gave Miami 29 points, 14 rebounds, three assists, two steals and two blocks in a 114–108 victory over Sacramento. Five turnovers kept the possession-protection side from being spotless, but his production across scoring, glass and defense was enough for 81.2 QPIX.','', 'Josh Giddey’s 19 points and 15 assists for Chicago and Darius Acuff Jr.’s 32 points and 10 assists for Sacramento illustrate another side of QPIX: playmaking counts even when a team loses. Meanwhile, Klay Thompson supplied 23 points and two blocks, with zero turnovers, for Miami.','', 'QPIX BOTTOM 10 — RAW SCORE','']
for i,p in enumerate(bottom,1):
    lines.append(f"{i}. {p['name']} ({p['team']}) — QPIX {p['raw_qpix_shadow']:.1f} | QPIX-R {p['qpix_r_shadow']:.1f}")
lines+=['', 'BOTTOM-PERFORMER CONTEXT','', 'Josh Okogie scored no points in 17 minutes, finishing with one rebound and one steal for Utah; his provisional -28.4 was the lowest RAW rating of the night. Herbert Jones contributed four points and one assist in 20 minutes for New Orleans and registered -28.0. Terance Mann finished with no points, one rebound and one assist across 22 minutes for Brooklyn and appeared in the Bottom 10 at -16.0. These are single-game evaluations, not judgments on a player’s season or overall ability.','', 'THE QPIX DIFFERENCE','', 'The same scoring engine that puts 43-point Reaves third places 25-point Flagg first and 12-point Robinson fourth. That is the purpose of QPIX: value shooting efficiency, rebounds, assists, steals, blocks, possession protection and game context together rather than using points alone as the scoreboard for individual impact. A steal that leads to an assist remains a steal and an assist — two separate contributions in the same possession.','', 'DATA AND METHODOLOGY DISCLOSURE','', 'PROVISIONAL SHADOW RESULTS — NOT OFFICIAL FULLY VERIFIED QPIX RAW. All 161 minutes-positive participants were scored with unchanged functions from main’s generate-report.js; strictly more than eight minutes were required for BOTH leaderboards (141 eligible). Individual C3 ratings were not available from the intended provider, so the November 5 QCore experimental Oliver-style Q-OffR/Q-DefR estimates were used for an explicitly labeled sensitivity run. Five short-minute players had uncomputable Q-OffR and remain in the complete records. Neither the QCore estimates nor NBA.com on-court ratings are represented as observed Basketball-Reference individual ratings.','', 'C6 individual paint, fast-break and second-chance points were missing for every player, and the fast-break component of C11 is unverified. These are unavailable inputs, not verified zeros; their computational treatment by the unchanged engine can change final scores when source data is recovered. QPIX-R is a provisional referee-normalized companion and QPIX-SFA did not produce a qualifying nonzero adjustment in this run. Full every-player JSON, CSV and a reproducibility audit accompany this shadow release.','', 'QCore Labs © 2026','QPIX™ — Because the box score never tells the whole story.']
out='\n'.join(lines)+'\n'
path=root/'docs/reports/2026-11-08.provisional.md'
